(() => {
'use strict';const W=HTWorkflow,esc=W.esc;
const hidden=W.read('hetu_removed_services_v3',[]),added=W.read('hetu_registered_services_v3',[]);
SVC.unshift(...added.filter(c=>!SVC.some(x=>x.id===c.id)));for(let i=SVC.length-1;i>=0;i--)if(hidden.includes(SVC[i].id))SVC.splice(i,1);
window.copyUrl=async function(value){const c=SVC.find(s=>s.id===value||s.title===value);const url=c?.extSrc||c?.url||'https://maps.hetu.example.com/svc/'+encodeURIComponent(c?.id||value);try{await navigator.clipboard.writeText(url);toast('服务地址已复制');}catch(_){const input=document.createElement('textarea');input.value=url;document.body.append(input);input.select();const ok=document.execCommand('copy');input.remove();toast(ok?'服务地址已复制':'服务地址：'+esc(url));}};
const beforeRegister=confirmRegister;
window.confirmRegister=function(){const raw=document.getElementById('regUrl').value.trim();try{const u=new URL(raw);if(!['http:','https:'].includes(u.protocol))throw Error();}catch(_){toast('请输入 http:// 或 https:// 开头的完整服务地址');return;}
 const ids=new Set(SVC.map(s=>s.id));beforeRegister();const c=SVC.find(s=>!ids.has(s.id));if(c){c.id=W.id('external-');c.updated=new Date().toISOString().slice(0,10);c.dataModel='矢量';c.geometry='面';c.asset=c.title;const all=W.read('hetu_registered_services_v3',[]);all.unshift(c);W.write('hetu_registered_services_v3',all);renderAll();}};
window.removeSvc=function(id){const c=SVC.find(s=>s.id===id);if(!c)return;const modal=document.createElement('div');modal.className='fixed inset-0 z-50 flex items-center justify-center';modal.style.background='rgba(0,0,0,.35)';modal.innerHTML='<div class="bg-white rounded-xl p-6" style="width:420px"><h3 class="font-semibold">删除服务</h3><p class="text-sm text-gray-600 mt-3">确定删除「'+esc(c.title)+'」？</p><div class="flex justify-end gap-3 mt-5"><button class="btn btn-default">取消</button><button class="btn btn-primary">删除</button></div></div>';document.body.append(modal);const [cancel,ok]=modal.querySelectorAll('button');cancel.onclick=()=>modal.remove();ok.onclick=()=>{const i=SVC.findIndex(s=>s.id===id);if(i>=0)SVC.splice(i,1);W.write('hetu_removed_services_v3',[...new Set([...W.read('hetu_removed_services_v3',[]),id])]);W.write('hetu_published_services_v2',W.services().filter(s=>s.id!==id));W.write('hetu_registered_services_v3',W.read('hetu_registered_services_v3',[]).filter(s=>s.id!==id));modal.remove();renderAll();toast('已删除服务');};};
const sync=()=>{const removed=W.read('hetu_removed_services_v3',[]);for(const s of W.services()){const old=SVC.find(x=>x.id===s.id);if(old)Object.assign(old,s);else if(!removed.includes(s.id))SVC.unshift({...s,sub:s.type+' · 平台发布',thumb:'from-brand-light to-brand/20'});}const dates=W.read('hetu_service_updates_v2',{});SVC.forEach(c=>{if(dates[c.id])c.updated=dates[c.id];});renderAll();};
window.addEventListener('storage',e=>{if(['hetu_published_services_v2','hetu_service_updates_v2'].includes(e.key))sync();});window.addEventListener('focus',sync);
renderAll();const params=new URLSearchParams(location.search);const target=SVC.find(s=>s.id===params.get('serviceId'))||SVC.find(s=>s.title===params.get('serviceName')||s.assetRef===params.get('serviceName'));
if(target)openDetail(target.id);else if(params.has('serviceName'))toast('未找到该任务关联的服务');
})();
